class Solution:
    def maximumLength(self, s: str) -> int:
        max_len = -1
        n = len(s)

        for length in range(1, n // 3 + 1):
            count = {}
            for i in range(n - length + 1):
                substr = s[i:i + length]
                if len(set(substr)) == 1:  # Check if the substring is special
                    count[substr] = count.get(substr, 0) + 1

            # Check if any of the special substrings appears at least thrice
            for k, v in count.items():
                if v >= 3:
                    max_len = length
                    break

        return max_len
